import numpy as np
from scipy import stats

def find_mode(L):
    def flatten(nested):
        result = []
        for item in nested:
            if isinstance(item, list):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result

    flat_list = flatten(L)
    arr = np.array(flat_list)
    mode_result = stats.mode(arr)
    return mode_result.mode[0].item()

