def convert_encoding(directory=DIRECTORY_PATH, from_encoding='cp1251', to_encoding='utf8') -> None:
    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)
        if os.path.isfile(filepath):
            try:
                with open(filepath, 'r', encoding=from_encoding) as f:
                    content = f.read()
                with open(filepath, 'w', encoding=to_encoding) as f:
                    f.write(content)
            except UnicodeDecodeError:
                continue  # Skip files that cannot be decoded with from_encoding

