import shutil
import pathlib

def copy_files(source_path, destination_path):
    source = pathlib.Path(source_path)
    if not source.exists() or not source.is_dir():
        raise ValueError("Source path does not exist or is not a directory")

    dest = pathlib.Path(destination_path)
    dest.mkdir(parents=True, exist_ok=True)

    filenames = []
    for entry in source.iterdir():
        if entry.is_file():
            shutil.copy(entry, dest)
            filenames.append(entry.name)

    return (source.name, filenames)

import base64
import hashlib
import os

def hash_password(password, SALT_LENGTH=32):
    if not password:
        raise ValueError("Password cannot be empty or None")
    salt = os.urandom(SALT_LENGTH)
    hashed = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, iterations=100000)
    return (base64.b64encode(salt), base64.b64encode(hashed))

