STEMMER = PorterStemmer()

def stem_frequency(content):
    words = content.split()
    if not words:
        return {}
    filtered_words = words[:-1]
    stems = []
    for word in filtered_words:
        cleaned_word = re.sub(r'[^\w]', '', word).lower()
