def extract_keys(obj):
    keys = []
    if isinstance(obj, dict):
        for k in obj:
            keys.append(k)
            keys.extend(extract_keys(obj[k]))
    elif isinstance(obj, list):
        for item in obj:
            keys.extend(extract_keys(item))
    return keys

