import base64
import hashlib
import os

def hash_password(password, salt_length=32):
    if not password:
        raise ValueError("Password cannot be empty")
    password_bytes = password.encode('utf-8')
    salt = os.urandom(salt_length)
    digest = hashlib.pbkdf2_hmac('sha256', password_bytes, salt, 100000)
    return (base64.b64encode(salt), base64.b64encode(digest))

