import collections
import json
import os
from typing import Dict, Any, Union

def count_json_keys(directory_path: str) -> Dict[str, int]:
    """
    Counts the total appearances of all keys in all JSON files in the specified directory.

    Args:
        directory_path: Path to the directory containing JSON files.

    Returns:
        A dictionary with the keys from the JSON files as keys and their respective counts as values.
    """
    key_counts = collections.defaultdict(int)

    def _count_keys(data: Union[dict, list]) -> None:
        if isinstance(data, dict):
            for key in data:
                key_counts[key] += 1
                _count_keys(data[key])
        elif isinstance(data, list):
            for item in data:
                _count_keys(item)

    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            filepath = os.path.join(directory_path, filename)
            with open(filepath, 'r') as f:
                data = json.load(f)
                _count_keys(data)

    return dict(key_counts)

