def count_characters(elements: list[str], include_index: bool = False) -> pd.DataFrame:
    """
    Construct a DataFrame enumerating character counts of each string in the elements list.

    Args:
    elements: A list of strings to count characters from.
    include_index: Optional flag to include an 'Index' column. Defaults to False.

    Returns:
    A pandas DataFrame with columns ['Element', 'Count'] or ['Index', 'Element', 'Count'] if include_index is True.
    """
    counts = [len(s) for s in elements]
    if include_index:
        indices = np.arange(len(elements))
        data = {'Index': indices, 'Element': elements, 'Count': counts}
    else:
        data = {'Element': elements, 'Count': counts}
    return pd.DataFrame(data)

