import random
from typing import Optional

def transform_text(text: str, seed: Optional[int] = None) -> str:
    """Transforms the input text by replacing each alphabetic character with a random letter of the same case.

    Args:
        text (str): The input text to be transformed.
        seed (Optional[int]): Optional seed for the random number generator. If provided, the transformation will be deterministic.

    Returns:
        str: The transformed string with random letters replacing the alphabetic characters, preserving non-alphabetic characters and original case.
    """
    if seed is not None:
        random.seed(seed)
    result = []
    for c in text:
        if c.isalpha():
            if c.isupper():
                replacement = random.choice(string.ascii_uppercase)
            else:
                replacement = random.choice(string.ascii_lowercase)
            result.append(replacement)
        else:
            result.append(c)
    return ''.join(result)

